            assert_eq!(span.contains(start), !span.is_empty());
            if start > 0 {
                assert!(!span.contains(start - 1), "offset before {span:?}");
            }
            if start < end {
                assert!(span.contains(end - 1), "last byte of {span:?}");
            }
